// Extract and assemble draft content from Notion blocks
const blocks = $input.all().map(i => i.json);
const draftMeta = $('Get Ready Draft').first().json;

let content = '';
for (const block of blocks) {
  if (block.type === 'paragraph' && block.paragraph?.rich_text) {
    const text = block.paragraph.rich_text.map(t => t.text?.content || t.plain_text || '').join('');
    content += text + '\n\n';
  } else if (block.type === 'heading_1' && block.heading_1?.rich_text) {
    const text = block.heading_1.rich_text.map(t => t.text?.content || t.plain_text || '').join('');
    content += `# ${text}\n\n`;
  } else if (block.type === 'heading_2' && block.heading_2?.rich_text) {
    const text = block.heading_2.rich_text.map(t => t.text?.content || t.plain_text || '').join('');
    content += `## ${text}\n\n`;
  } else if (block.type === 'heading_3' && block.heading_3?.rich_text) {
    const text = block.heading_3.rich_text.map(t => t.text?.content || t.plain_text || '').join('');
    content += `### ${text}\n\n`;
  } else if (block.type === 'bulleted_list_item' && block.bulleted_list_item?.rich_text) {
    const text = block.bulleted_list_item.rich_text.map(t => t.text?.content || t.plain_text || '').join('');
    content += `• ${text}\n`;
  }
}

const title = draftMeta.properties?.title?.title?.[0]?.text?.content ||
  draftMeta.properties?.Name?.title?.[0]?.text?.content || 'The Prompt — Weekly Brief';

return {
  json: {
    title,
    content: content.trim(),
    notion_page_id: draftMeta.id,
    published_at: new Date().toISOString()
  }
};

