// Parse social posts from Claude and prepare outputs
const claudeResponse = $input.item.json;
const content = $('Assemble Content').first().json;

let posts = [];
try {
  const text = claudeResponse.content?.[0]?.text || '';
  const cleaned = text.replace(/```json\n?|```\n?/g, '').trim();
  posts = JSON.parse(cleaned);
} catch {
  posts = [
    { platform: 'linkedin', text: `New edition of The Prompt is live: ${content.title}. Read it on Substack.` },
    { platform: 'twitter', text: `New: ${content.title} — this week in AI ecosystem intelligence. Link in bio.` }
  ];
}

const linkedin = posts.find(p => p.platform === 'linkedin')?.text || '';
const twitter = posts.find(p => p.platform === 'twitter')?.text || '';

return {
  json: {
    ...content,
    linkedin_post: linkedin,
    twitter_post: twitter
  }
};
